export function t(key, values = {}) {
  let value = key.split('.').reduce((node, part) => node?.[part], messages[locale]);
  if (typeof value !== 'string') return value ?? key;
  return value.replace(/\{(\w+)\}/g, (_, token) => String(values[token] ?? ''));
}
